const timeFromRaw = (r: RawRecipe) => r.s.map(([mins, text]) => `${text} (-${mins}m)`);

export const WORLD_RECIPES: Meal[] = RAW.map((r) => ({
  id: r.id,
  title: r.t,
  description: r.d,
  cuisine: r.c,
  timeStake: r.ts,
  effort: r.e,
  ingredients: r.i,
  prepSteps: timeFromRaw(r),
  rating: 0,
  isFavorite: false,
  lastCookedDate: null,
  cookCount: 0,
  tags: [r.r, ...(r.tags || [])],
  servings: 4,
  origin: r.r,
  source: 'world',
}));

/** Wikipedia article used to look up each dish's photo (consumed by scripts/fetch-photos.mjs). */
export const WORLD_RECIPE_WIKI: Record<string, string> = Object.fromEntries(RAW.map((r) => [r.id, r.w]));
